package com.yuegang.zhihui.search.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.search.api.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.*;import org.springframework.web.client.*;
public final class IndexLifecycleService{private final JdbcTemplate jdbc;private final RestClient elastic;private final String alias;public IndexLifecycleService(JdbcTemplate j,String es,String a){jdbc=j;elastic=RestClient.builder().baseUrl(es).build();alias=a;}public IndexVersionView status(){return jdbc.query("SELECT alias_name,active_version,previous_version,switched_at,(SELECT COUNT(*) FROM search_embedding e WHERE e.index_version=v.active_version) FROM search_index_version v WHERE alias_name=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new IndexVersionView(r.getString(1),r.getString(2),r.getString(3),r.getLong(5),r.getTimestamp(4).toLocalDateTime().atOffset(ZoneOffset.UTC));},alias);}public void create(String version){valid(version);elastic.put().uri("/"+version).body(Map.of("mappings",Map.of("properties",Map.of("documentId",Map.of("type","keyword"),"chunkId",Map.of("type","keyword"),"title",Map.of("type","text"),"content",Map.of("type","text"),"category",Map.of("type","keyword"),"visibility",Map.of("type","keyword"))))).retrieve().toBodilessEntity();}public IndexVersionView switchTo(SwitchIndexRequest c){valid(c.version());Long count=jdbc.queryForObject("SELECT COUNT(*) FROM search_embedding WHERE index_version=?",Long.class,c.version());if(count==null||count<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);Map<String,Object>actions=new LinkedHashMap<>();var body=Map.of("actions",List.of(Map.of("remove",Map.of("index","*","alias",alias,"must_exist",false)),Map.of("add",Map.of("index",c.version(),"alias",alias))));elastic.post().uri("/_aliases").body(body).retrieve().toBodilessEntity();int changed=jdbc.update("UPDATE search_index_version SET previous_version=active_version,active_version=?,switched_at=NOW() WHERE alias_name=?",c.version(),alias);if(changed!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return status();}public void deletePrevious(){var s=status();if(s.previousVersion()==null)return;if(s.previousVersion().equals(s.activeVersion()))throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);elastic.delete().uri("/"+s.previousVersion()).retrieve().toBodilessEntity();jdbc.update("DELETE FROM search_embedding WHERE index_version=?",s.previousVersion());jdbc.update("UPDATE search_index_version SET previous_version=NULL WHERE alias_name=?",alias);}private static void valid(String x){if(x==null||!x.matches("[a-z0-9][a-z0-9._-]{1,63}"))throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}
